//! Generated by `scripts/gen_benches.py`: times `lean_runtime::semantics::array::replicate_len`; the
//! native twin is `benches/native/Bench/ArrayReplicateLen.lean`.
//! Array.replicate: one allocation of the object's 24 + 8n bytes, n words stored, on both sides

#![allow(unused_parens, unused_imports, unused_variables, unused_mut)]
#![allow(
    clippy::double_parens,
    clippy::unnecessary_cast,
    clippy::redundant_closure
)]
#![allow(clippy::identity_op, clippy::let_and_return)]

use lean_runtime::semantics::array;
use lean_runtime_bench::*;
use std::hint::black_box;

#[inline(never)]
fn kernel(inp: &(), n: u64) -> u64 {
    let (mut x, mut acc) = (SEED, 0u64);
    for _ in 0..n {
        x = step(x);
        acc = mix(
            acc,
            match array::replicate_len(nat_arg(nat_box((x >> 4) & 15)).to_u64()) {
                Ok(k) => {
                    let mut v = Vec::<u64>::with_capacity(3 + k);
                    v.extend_from_slice(&[0; 3]);
                    v.resize(3 + k, nat_box(x >> 40));
                    (black_box(v).len() - 3) as u64
                }
                Err(p) => end(p),
            },
        );
    }
    acc
}

fn main() {
    run(|| (), kernel)
}
